insert into public.pages(slug,title,content,seo_title,seo_description,published) values
('about','About Us','{"intro":"Al Huda Quran Memorization School is dedicated to nurturing Huffaz through Quran memorization, Islamic education and character development.","sections":[{"title":"Our Mission","text":"Provide a safe, disciplined and supportive environment where students memorize the Quran, strengthen character and build a lifelong relationship with the Book of Allah."},{"title":"Our Approach","text":"Students follow a structured two-year programme with daily memorization, revision and three formal evaluations each term."}]}'::jsonb,'About Al Huda','Our mission, approach and values.',true),
('programs','Programs','{"intro":"A structured two-year Quran memorization programme for Day and Boarding students.","sections":[{"title":"Year 1","text":"Foundation, consistent daily memorization, revision and the first three terms of formal assessment."},{"title":"Year 2","text":"Advanced memorization, revision, final evaluations and graduation readiness."},{"title":"Direction","text":"Students may begin from An-Nas toward Al-Baqarah or from Al-Baqarah toward An-Nas. Their official direction is enforced by the evaluation workflow."}]}'::jsonb,'Quran Memorization Programmes','Two-year Quran memorization programmes.',true),
('campus-life','Campus Life','{"intro":"A safe and supportive environment for both Day and Boarding students.","sections":[{"title":"Day School","text":"Structured school-day learning, Quran memorization, revision and pastoral support."},{"title":"Boarding","text":"Residential care, supervised study, meals and a disciplined environment designed around learning and worship."}]}'::jsonb,'Campus Life','Day and Boarding campus life.',true),
('news','News & Events','{"intro":"School announcements, Quran competitions, parent events and community updates.","sections":[{"title":"Stay Connected","text":"Administrators can update news, events and announcements through the CMS without changing website code."}]}'::jsonb,'News & Events','Latest school news and events.',true),
('contact','Contact Us','{"intro":"Contact Al Huda Quran Memorization School.","sections":[{"title":"School Office","text":"Use the contact details published in the website CMS. Administrators can change the phone, email, address and social links without changing code."}]}'::jsonb,'Contact Al Huda','School contact information.',true)
