-- Database-backed homepage content seed. Safe to rerun.
on conflict(key) do nothing;

on conflict(section_key) do update set title=excluded.title, content=excluded.content, sort_order=excluded.sort_order, visible=excluded.visible, updated_at=now();

on conflict(slug) do update set title=excluded.title,content=excluded.content,seo_title=excluded.seo_title,seo_description=excluded.seo_description,published=true,updated_at=now();
